M(fnc, r"""
public static String repl(String r, String t, String nm) {
  if (r == null || t == null || nm == null || t.length() == 0 || t.equals(nm)) return r;
  StringBuilder sb = new StringBuilder();
  int from = 0;
  int guard = 0;
  while (guard < 20) {
    guard = guard + 1;
    int i = r.indexOf(t, from);
    if (i < 0) break;
    int e = i + t.length();
    boolean digit = e < r.length() && r.charAt(e) >= '0' && r.charAt(e) <= '9';
    sb.append(r.substring(from, i)).append(digit ? t : nm);
    from = e;
  }
  sb.append(r.substring(from));
  return sb.toString();
}""")
